param([string]$Port='COM4',[Parameter(Mandatory=$true)][string]$LocalPath,[Parameter(Mandatory=$true)][string]$RemotePath)
$ErrorActionPreference='Stop'
$s=[IO.Ports.SerialPort]::new($Port,115200,[IO.Ports.Parity]::None,8,[IO.Ports.StopBits]::One);$s.Handshake='None';$s.ReadTimeout=200;$s.WriteTimeout=1000;$s.Encoding=[Text.Encoding]::UTF8
$sb=[Text.StringBuilder]::new(); function ReadNow{$x=$s.ReadExisting();if($x.Length){[void]$sb.Append($x);[Console]::Write($x)}}; function Send($x){$s.Write($x+"`r")}; function Prompt{$d=(Get-Date).AddSeconds(60);while((Get-Date)-lt$d){ReadNow;if($sb.ToString()-match '(?m)[#\$]\s*$'){return};if($sb.ToString()-match '(?im)login\s*:\s*$'){Send root};if($sb.ToString()-match '(?im)(password|密码)\s*[:：>]?\s*$'){Send root};Start-Sleep -Milliseconds 50};throw 'prompt timeout'}
try{$s.Open();Send '';Prompt;$b64=[Convert]::ToBase64String([IO.File]::ReadAllBytes($LocalPath));Send "stty -icanon min 1 time 0 -echo; base64 -d > $RemotePath";Start-Sleep -Milliseconds 500;for($i=0;$i-lt$b64.Length;$i+=1024){$n=[Math]::Min(1024,$b64.Length-$i);$s.Write($b64.Substring($i,$n));Start-Sleep -Milliseconds 8};$s.Write("`r");Start-Sleep -Milliseconds 2000;$s.BaseStream.Write([byte[]](4),0,1);Start-Sleep -Milliseconds 1000;ReadNow;Send 'stty sane';Start-Sleep -Milliseconds 700;ReadNow;Send '';Prompt;Write-Host "UPLOADED $LocalPath -> $RemotePath"}finally{if($s.IsOpen){$s.Close()};$s.Dispose()}
